CREATE TABLE Source(id INTEGER PRIMARY KEY, cents INTEGER NOT NULL);
CREATE TABLE Target(id INTEGER NOT NULL, amount_units REAL NOT NULL);
INSERT INTO Source VALUES(1,1250),(2,2750);
INSERT INTO Target VALUES(1,1250),(2,2750);
SELECT
 (SELECT COUNT(*) FROM Target) AS target_rows,
 (SELECT COUNT(DISTINCT id) FROM Target) AS distinct_ids,
 (SELECT COUNT(*) FROM Source s WHERE NOT EXISTS(SELECT 1 FROM Target t WHERE t.id=s.id)) AS missing_ids,
 (SELECT COUNT(*) FROM Source s JOIN Target t ON t.id=s.id WHERE t.amount_units<>s.cents/100.0) AS wrong_amount_rows;

